def _validate_evaluate_many_payload(data, name):
    """校验一份 ppo_evaluate_many 完整返回值，返回 results 项列表。"""
    if list(data) != ["results", "means", "passed", "converged"]:
        raise ValueError(
            f"{name} must have exactly the keys results, means,"
            " passed, converged"
        )
    entries = data["results"]
